  var matched = false;
  while (pos < spec.length) {
    final match = token.matchAsPrefix(spec, pos);
    if (match == null) {
      throw FormatException(
        'invalid deadline "$spec" — expected a duration like 25m, 90s or '
        '1h30m, or an epoch-ms timestamp',
