  /// Creates a notice.
  const DeadlineNotice(this.kind, this.text);

  /// Which ladder crossing fired.
  final DeadlineNoticeKind kind;

  /// The model-facing steering text (already rendered with the current
  /// remaining budget).
  final String text;

  @override
